//! Replays independent protobuf and base64 vectors generated by Lean.

use fireemu_core_storage::etag::{bucket_etag, production_etag};

#[test]
fn calculated_etags_follow_the_lean_reference() {
    let fixture = include_str!("fixtures/lean-storage-etag.corpus");
    let mut rows = fixture.lines();
    let count: usize = rows
        .next()
        .unwrap()
        .strip_prefix("# ")
        .unwrap()
        .parse()
        .unwrap();
    assert!(count >= 350);
    assert_eq!(rows.clone().count(), count);
    for row in rows {
        let [kind, generation, metageneration, octets]: [&str; 4] = row
            .split('\t')
            .collect::<Vec<_>>()
            .try_into()
            .expect("kind, generation, metageneration, expected ETag octets");
        let metageneration = metageneration.parse::<u64>().unwrap();
        let actual = match kind {
            "object" => production_etag(generation.parse::<u64>().unwrap(), metageneration),
            "bucket" => {
                assert_eq!(generation, "-");
                bucket_etag(metageneration)
            }
            _ => panic!("unknown etag kind {kind}"),
        };
        let expected = octets
            .split('.')
            .map(|octet| octet.parse::<u8>().expect("expected an ASCII octet"))
            .collect::<Vec<_>>();
        assert_eq!(actual.as_bytes(), expected, "fixture {row}");
    }
}
